python3 -I - <<'PY'
import json
from pathlib import Path
root=Path('/workspace/observed_run')
for rel in ['dump_details/events/main.jsonl','dump_details/events/rollout_executor.jsonl']:
    rows=[json.loads(x) for x in (root/rel).read_text().splitlines()]
    print('\n',rel, 'events:',len(rows),'types:', sorted({r.get('type','') for r in rows}))
    for r in rows:
        text=json.dumps(r,ensure_ascii=False)
        if 'Using message matcher' in text or 'tito_model=' in text or r.get('type')=='env_report':
            if r.get('type')=='env_report':
                argv=r['report']['process']['argv']
                wanted={'--tito-model','--sglang-tool-call-parser','--sglang-reasoning-parser','--session-message-matcher','--use-session-server','--session-sample-picker-path','--session-sample-postprocessor-path','--hf-checkpoint'}
                print('env_report selected argv:',[argv[i]+' '+argv[i+1] for i in range(len(argv)-1) if argv[i] in wanted])
            else: print(json.dumps(r,ensure_ascii=False))
PY

